**完整参考实现（非原书摘录）**

约定：行、列从 1 开始，输入三元组按 (i,j) 严格递增、坐标合法且元素非零。AddSub 的 sign 为 1 或 -1，分别计算和、差；Multiply 计算积。维数不匹配、容量不足或算术溢出时返回错误且不改写输出。rpos[i] 是第 i 行首项，rpos[mu+1]=tu+1。

~~~~c
#include <limits.h>
#define MAXRC 20
#define MAXTERM (MAXRC*MAXRC)
typedef long long E; typedef enum { OK,DIM_ERROR,CAPACITY_ERROR,ARITH_ERROR } Status;
typedef struct {int i,j;E e;} Triple;
typedef struct {Triple data[MAXTERM+1];int mu,nu,tu,rpos[MAXRC+2];} RLS;
static void Rpos(RLS*m){int p=1;for(int i=1;i<=m->mu;i++){m->rpos[i]=p;while(p<=m->tu&&m->data[p].i==i)p++;}m->rpos[m->mu+1]=m->tu+1;}
static Status Put(RLS*m,int i,int j,E e){if(!e)return OK;if(m->tu==MAXTERM)return CAPACITY_ERROR;m->data[++m->tu]=(Triple){i,j,e};return OK;}
static int Before(Triple x,Triple y){return x.i<y.i||(x.i==y.i&&x.j<y.j);} static int Fits(__int128 x){return x>=LLONG_MIN&&x<=LLONG_MAX;}
Status AddSub(const RLS*a,const RLS*b,int sign,RLS*out){
 if(!a||!b||!out||(sign!=1&&sign!=-1)||a->mu!=b->mu||a->nu!=b->nu)return DIM_ERROR;RLS c={.mu=a->mu,.nu=a->nu};int p=1,q=1;
 while(p<=a->tu||q<=b->tu){Status s;if(q>b->tu||(p<=a->tu&&Before(a->data[p],b->data[q])))s=Put(&c,a->data[p].i,a->data[p].j,a->data[p++].e);else if(p>a->tu||Before(b->data[q],a->data[p])){__int128 v=(__int128)sign*b->data[q].e;if(!Fits(v))return ARITH_ERROR;s=Put(&c,b->data[q].i,b->data[q].j,(E)v);q++;}else{__int128 v=(__int128)a->data[p].e+(__int128)sign*b->data[q].e;if(!Fits(v))return ARITH_ERROR;s=Put(&c,a->data[p].i,a->data[p].j,(E)v);p++;q++;}if(s!=OK)return s;}Rpos(&c);*out=c;return OK;
}
Status Multiply(const RLS*a,const RLS*b,RLS*out){
 if(!a||!b||!out||a->nu!=b->mu)return DIM_ERROR;RLS c={.mu=a->mu,.nu=b->nu};for(int i=1;i<=a->mu;i++){__int128 sum[MAXRC+1]={0};for(int p=a->rpos[i];p<a->rpos[i+1];p++){int k=a->data[p].j;for(int q=b->rpos[k];q<b->rpos[k+1];q++)sum[b->data[q].j]+=(__int128)a->data[p].e*b->data[q].e;}for(int j=1;j<=b->nu;j++){if(!Fits(sum[j]))return ARITH_ERROR;Status s=Put(&c,i,j,(E)sum[j]);if(s!=OK)return s;}}Rpos(&c);*out=c;return OK;
}
~~~~

可复验样例：A 为 (1,1,10),(2,3,9),(3,1,-1)，B 为 (2,3,-1),(3,1,1),(3,3,-3)，分别建 rpos 后相加得到 [[10,0,0],[0,0,8],[0,0,-3]]。乘法题例左上角为 4×3+(-3)×(-4)+1×0=24，程序第一行是 [24,-6,0]；题面 [0,-6,0] 与其数据不一致。

归并不变式为 C 已写前缀恰是已处理坐标的和或差；内层累积恰为点积。加减时间 O(tuA+tuB)、空间 O(1)；乘法时间 O(muA·nuB+Σ使用的B行非零数)，工作空间 O(nuB)。

**完整参考实现（非原书摘录）**

约定：严格按题设分离 NArray 类型记录和 NArrayType 对象；行优先，维数 1..MaxDim，各维闭区间可从任意 int 起始。初始化对象须清零，失败不改变它；读写下标长度为维数，完整赋值要求各维上下界相同。

~~~~c
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#define MaxDim 5
typedef int ElemType; typedef enum {OK,ERROR,OVERFLOW,NO_MEMORY,TYPE_MISMATCH} Status;
typedef struct {int dim;int*lower,*upper;size_t*constants;} NArray,*NArrayPtr;
typedef struct {ElemType*elem;int num;NArrayPtr TypeRecord;} NArrayType;
void DestroyNArray(NArrayType*a){if(!a)return;free(a->elem);if(a->TypeRecord){free(a->TypeRecord->lower);free(a->TypeRecord->upper);free(a->TypeRecord->constants);free(a->TypeRecord);}*a=(NArrayType){0};}
Status Locate(const NArrayType*a,const int sub[],size_t*off){const NArray*r=a?a->TypeRecord:NULL;if(!r||!sub||!off)return ERROR;size_t k=0;for(int d=0;d<r->dim;d++){if(sub[d]<r->lower[d]||sub[d]>r->upper[d])return ERROR;k+=(size_t)((int64_t)sub[d]-r->lower[d])*r->constants[d];}if(k>=(size_t)a->num)return ERROR;*off=k;return OK;}
Status InitNArray(NArrayType*a,int dim,const int lo[],const int hi[]){
 if(!a||a->elem||a->TypeRecord||a->num||!lo||!hi||dim<1||dim>MaxDim)return ERROR;NArray*r=calloc(1,sizeof*r);if(!r)return NO_MEMORY;r->lower=malloc(dim*sizeof*r->lower);r->upper=malloc(dim*sizeof*r->upper);r->constants=malloc(dim*sizeof*r->constants);if(!r->lower||!r->upper||!r->constants){free(r->lower);free(r->upper);free(r->constants);free(r);return NO_MEMORY;}size_t n=1,w[MaxDim];r->dim=dim;
 for(int d=0;d<dim;d++){int64_t z=(int64_t)hi[d]-lo[d]+1;if(z<=0||(uint64_t)z>SIZE_MAX||n>SIZE_MAX/(size_t)z||n>(size_t)INT_MAX/(size_t)z){free(r->lower);free(r->upper);free(r->constants);free(r);return OVERFLOW;}r->lower[d]=lo[d];r->upper[d]=hi[d];w[d]=(size_t)z;n*=w[d];}r->constants[dim-1]=1;for(int d=dim-2;d>=0;d--){if(r->constants[d+1]>SIZE_MAX/w[d+1]){free(r->lower);free(r->upper);free(r->constants);free(r);return OVERFLOW;}r->constants[d]=r->constants[d+1]*w[d+1];}ElemType*e=calloc(n,sizeof*e);if(!e){free(r->lower);free(r->upper);free(r->constants);free(r);return NO_MEMORY;}a->elem=e;a->num=(int)n;a->TypeRecord=r;return OK;
}
Status Get(const NArrayType*a,const int s[],ElemType*v){size_t k;if(!v||Locate(a,s,&k)!=OK)return ERROR;*v=a->elem[k];return OK;} Status Set(NArrayType*a,const int s[],ElemType v){size_t k;if(Locate(a,s,&k)!=OK)return ERROR;a->elem[k]=v;return OK;}
static int Same(const NArrayType*a,const NArrayType*b){if(!a||!b||!a->TypeRecord||!b->TypeRecord||a->num!=b->num||a->TypeRecord->dim!=b->TypeRecord->dim)return 0;for(int d=0;d<a->TypeRecord->dim;d++)if(a->TypeRecord->lower[d]!=b->TypeRecord->lower[d]||a->TypeRecord->upper[d]!=b->TypeRecord->upper[d])return 0;return 1;}
Status Assign(NArrayType*d,const NArrayType*s){if(!Same(d,s))return TYPE_MISMATCH;memmove(d->elem,s->elem,(size_t)s->num*sizeof*s->elem);return OK;}
Status SubAssign(NArrayType*d,const int dl[],const int dh[],const NArrayType*s,const int sl[],const int sh[]){
 if(!d||!s||!d->TypeRecord||!s->TypeRecord||!dl||!dh||!sl||!sh||d->TypeRecord->dim!=s->TypeRecord->dim)return TYPE_MISMATCH;int dim=s->TypeRecord->dim,rel[MaxDim],si[MaxDim],di[MaxDim];size_t len[MaxDim],n=1;for(int k=0;k<dim;k++){if(sl[k]<s->TypeRecord->lower[k]||sh[k]>s->TypeRecord->upper[k]||dl[k]<d->TypeRecord->lower[k]||dh[k]>d->TypeRecord->upper[k])return ERROR;int64_t x=(int64_t)sh[k]-sl[k]+1,y=(int64_t)dh[k]-dl[k]+1;if(x<=0||x!=y||(uint64_t)x>SIZE_MAX||n>SIZE_MAX/(size_t)x)return ERROR;len[k]=(size_t)x;n*=len[k];}if(n>SIZE_MAX/sizeof(ElemType))return OVERFLOW;ElemType*tmp=malloc(n*sizeof*tmp);if(!tmp)return NO_MEMORY;
 for(size_t p=0;p<n;p++){size_t x=p,o;for(int k=dim-1;k>=0;k--){rel[k]=x%len[k];x/=len[k];si[k]=sl[k]+rel[k];}if(Locate(s,si,&o)!=OK){free(tmp);return ERROR;}tmp[p]=s->elem[o];}for(size_t p=0;p<n;p++){size_t x=p,o;for(int k=dim-1;k>=0;k--){rel[k]=x%len[k];x/=len[k];di[k]=dl[k]+rel[k];}if(Locate(d,di,&o)!=OK){free(tmp);return ERROR;}d->elem[o]=tmp[p];}free(tmp);return OK;
}
~~~~

可复验样例：用下界 {1,3}、上界 {3,5} 建 3×3 数组，令 a[i,j]=10*i+j。执行 SubAssign 的目标 {1,3}..{3,4}、源 {1,4}..{3,5} 后，每行 [10i+3,10i+4,10i+5] 变为 [10i+4,10i+5,10i+5]。越界、维数不同、长度不同均返回错误且不写入；临时缓冲保证前后移和多维重叠安全。

constants[d] 是第 d 维加一跳过的后缀元素数。初始化 O(dim)，读写 O(dim)，完整赋值 O(num)，P 元素子数组赋值 O(P·dim) 时间、O(P+dim) 空间。

**完整参考实现（非原书摘录）**

约定：NULL 是空表；ATOM 保存完整字母数字串；LIST.hp 是首项，LIST.tp 是余项。语法为 List := '(' [Item {',' Item}] ')'、Item := List 或 alnum+；跨行空白被忽略。非法原子、连续逗号、空项、未配对括号及尾随字符都失败并释放结点。解析只前向读取一次，不先用 hsub/tsub 扫描嵌套边界。

~~~~c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef enum {ATOM,LIST} Tag; typedef struct N{Tag tag;union{char*atom;struct{struct N*hp,*tp;}p;}u;}N,*GList; typedef struct{const char*s;size_t pos,n;int ok;}P;
static void Free(GList x){if(!x)return;if(x->tag==ATOM)free(x->u.atom);else{Free(x->u.p.hp);Free(x->u.p.tp);}free(x);} static void Skip(P*p){while(p->pos<p->n&&isspace((unsigned char)p->s[p->pos]))p->pos++;} static GList Item(P*p);
static GList List(P*p){if(p->pos>=p->n||p->s[p->pos++]!='('){p->ok=0;return NULL;}Skip(p);if(p->pos<p->n&&p->s[p->pos]==')'){p->pos++;return NULL;}GList h=NULL,*tail=&h;for(;;){GList x=Item(p);if(!p->ok){Free(h);return NULL;}GList c=malloc(sizeof*c);if(!c){Free(x);Free(h);p->ok=0;return NULL;}c->tag=LIST;c->u.p.hp=x;c->u.p.tp=NULL;*tail=c;tail=&c->u.p.tp;Skip(p);if(p->pos>=p->n){Free(h);p->ok=0;return NULL;}if(p->s[p->pos]==')'){p->pos++;return h;}if(p->s[p->pos++]!=','){Free(h);p->ok=0;return NULL;}Skip(p);if(p->pos>=p->n||p->s[p->pos]==','||p->s[p->pos]==')'){Free(h);p->ok=0;return NULL;}}}
static GList Item(P*p){Skip(p);if(p->pos<p->n&&p->s[p->pos]=='(')return List(p);size_t b=p->pos;while(p->pos<p->n&&isalnum((unsigned char)p->s[p->pos]))p->pos++;if(b==p->pos){p->ok=0;return NULL;}GList x=malloc(sizeof*x);char*w=malloc(p->pos-b+1);if(!x||!w){free(x);free(w);p->ok=0;return NULL;}memcpy(w,p->s+b,p->pos-b);w[p->pos-b]=0;x->tag=ATOM;x->u.atom=w;return x;}
GList Create(const char*s,int*ok){P p={s,0,s?strlen(s):0,s!=NULL};Skip(&p);GList x=p.ok?List(&p):NULL;Skip(&p);if(!p.ok||p.pos!=p.n){Free(x);x=NULL;p.ok=0;}if(ok)*ok=p.ok;return x;} void Print(GList x){if(!x){putchar('(');putchar(')');return;}if(x->tag==ATOM){for(char*p=x->u.atom;*p;p++)putchar(*p);return;}putchar('(');for(GList p=x;p;p=p->u.p.tp){Print(p->u.p.hp);if(p->u.p.tp)putchar(',');}putchar(')');}
int Ops(GList root,const char*ops,GList*out){GList x=root;for(size_t i=0;ops&&ops[i];i++){if(!x||x->tag!=LIST||(ops[i]!='h'&&ops[i]!='t'))return 0;x=ops[i]=='h'?x->u.p.hp:x->u.p.tp;}*out=x;return 1;}
~~~~

字符串演示函数仍可按题意实现：test 返 N/E/O；hsub 在深度零的首逗号前取首项；tsub 取逗号后缀；strip 仅剥去覆盖全串的首尾括号。

可复验样例：输入 ((),(e1),(abc,(e2,c,dd)))，Ops(root,'tth',&r) 成功，Print(r) 输出 (abc,(e2,c,dd))；输入 (a,,b) 建表失败；当前值为空表或原子后继续 h/t 失败。r 与 root 共享结点，只能最终 Free(root) 一次。

结构归纳表明每项恰接为一个头尾单元。长度 L 的建表时间和存储 O(L)，递归栈 O(嵌套深度)，q 个操作 O(q)，打印 O(结果长度)。

**完整参考实现（非原书摘录）**

约定：基本文法为 Expr := digit 或 '(' '+' Expr Expr ')'；digit 仅 0..9，空白可在任意记号之间。每行只允许一个表达式；空行、缺符号/操作数/右括号、尾随字符和超出 int 的结果为错误。以 Status Evaluate(FILE*,int*) 替代无法报告错误的单一 int 接口，成功才写 out。

~~~~c
#include <ctype.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
typedef enum {OK,SYNTAX_ERROR,RANGE_ERROR,IO_ERROR,NO_MEMORY} Status;
static void Skip(const char**p){while(isspace((unsigned char)**p))++*p;} static int Add(long long a,long long b,long long*s){if((b>0&&a>LLONG_MAX-b)||(b<0&&a<LLONG_MIN-b))return 0;*s=a+b;return 1;}
static Status Expr(const char**p,long long*v){Skip(p);if(**p>='0'&&**p<='9'){*v=*(*p)++-'0';return OK;}if(**p!='(')return SYNTAX_ERROR;++*p;Skip(p);if(**p!='+')return SYNTAX_ERROR;++*p;long long a,b;Status s=Expr(p,&a);if(s!=OK||(s=Expr(p,&b))!=OK)return s;Skip(p);if(**p!=')')return SYNTAX_ERROR;++*p;return Add(a,b,v)?OK:RANGE_ERROR;}
Status EvaluateLine(const char*line,int*out){if(!line||!out)return IO_ERROR;const char*p=line;long long v;Status s=Expr(&p,&v);if(s!=OK)return s;Skip(&p);if(*p!=0)return SYNTAX_ERROR;if(v<INT_MIN||v>INT_MAX)return RANGE_ERROR;*out=(int)v;return OK;}
static Status ReadLine(FILE*f,char**out){size_t n=0,c=64;int ch;char*s=malloc(c);if(!s)return NO_MEMORY;while((ch=fgetc(f))!=EOF&&ch!=10){if(n+1==c){char*t=realloc(s,c*2);if(!t){free(s);return NO_MEMORY;}s=t;c*=2;}s[n++]=ch;}if(ch==EOF&&n==0){free(s);return IO_ERROR;}s[n]=0;*out=s;return OK;}
Status Evaluate(FILE*f,int*out){char*s;Status r=ReadLine(f,&s);if(r!=OK)return r;r=EvaluateLine(s,out);free(s);return r;}
~~~~

可复验样例：题给五行依次输出 6、9、15、15、36。表达式 (+4)、(+4x)、(+4 5 和 (+4 5)) 都返回 SYNTAX_ERROR。相加先在 long long 检查溢出，再检查能否存入 int。

数字基例直接正确；括号式仅在两个子式成功且右括号匹配后求和，故结构归纳正确。每字符常数次处理，时间 O(L)，栈 O(depth)。多位整数或四则运算必须另改词法和文法。
